"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/data-export-progress.css";
import { ArrowCounterClockwise, CheckCircle, DownloadSimple, WarningCircle, X } from "@phosphor-icons/react";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../../lib/cn";
import { Button } from "./button";
import { IconButton } from "./icon-button";
import { Progress } from "./progress";

export type DataExportProgressStatus = "idle" | "running" | "complete" | "error" | "cancelled";

export type DataExportProgressProps = HTMLAttributes<HTMLDivElement> & {
  status: DataExportProgressStatus;
  progress?: number;
  title?: ReactNode;
  description?: ReactNode;
  fileName?: string;
  processedRows?: number;
  totalRows?: number;
  onCancel?: () => void;
  onRetry?: () => void;
  onDownload?: () => void;
};

export function DataExportProgress({
  status,
  progress = 0,
  title,
  description,
  fileName,
  processedRows,
  totalRows,
  onCancel,
  onRetry,
  onDownload,
  className,
  ...props
}: DataExportProgressProps) {
  const value = Math.max(0, Math.min(100, progress));
  const defaultTitle = status === "running" ? "Preparing export" : status === "complete" ? "Export ready" : status === "error" ? "Export failed" : status === "cancelled" ? "Export cancelled" : "Export queued";
  const rowDetail = typeof processedRows === "number" && typeof totalRows === "number" ? `${processedRows.toLocaleString()} of ${totalRows.toLocaleString()} rows` : null;
  const role = status === "error" ? "alert" : "status";
  return (
    <div className={cn("whatiuse-data-export-progress", className)} data-status={status} role={role} aria-live="polite" {...props}>
      <div className="whatiuse-data-export-progress__icon" aria-hidden="true">
        {status === "complete" ? <CheckCircle weight="fill" /> : status === "error" ? <WarningCircle /> : status === "cancelled" ? <X /> : <DownloadSimple />}
      </div>
      <div className="whatiuse-data-export-progress__content">
        <div className="whatiuse-data-export-progress__heading">
          <strong>{title ?? defaultTitle}</strong>
          <span>{description ?? rowDetail ?? fileName}</span>
        </div>
        {status === "running" && <Progress aria-label="Export progress" value={value} showValue size="small" />}
      </div>
      <div className="whatiuse-data-export-progress__actions">
        {status === "running" && onCancel && <IconButton size="small" variant="ghost" aria-label="Cancel export" onClick={onCancel}><X aria-hidden="true" /></IconButton>}
        {(status === "error" || status === "cancelled") && onRetry && <Button size="small" variant="secondary" leadingIcon={<ArrowCounterClockwise />} onClick={onRetry}>Retry</Button>}
        {status === "complete" && onDownload && <Button size="small" variant="secondary" leadingIcon={<DownloadSimple />} onClick={onDownload}>Download</Button>}
      </div>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-data-export-progress {
  display: grid;
  width: min(520px, 100%);
  min-width: 0;
  min-height: 66px;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border-radius: 10px;
  background: var(--whatiuse-bg-surface);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-control-border) 58%, transparent), var(--whatiuse-shadow-control);
}

.whatiuse-data-export-progress__icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 8px;
  background: var(--whatiuse-bg-subtle);
  color: var(--whatiuse-fg-muted);
}

.whatiuse-data-export-progress__icon svg { width: 15px; height: 15px; }

.whatiuse-data-export-progress[data-status="error"] .whatiuse-data-export-progress__icon { background: color-mix(in oklch, var(--whatiuse-fg-danger) 9%, transparent); color: var(--whatiuse-fg-danger); }

.whatiuse-data-export-progress__content { display: grid; min-width: 0; gap: 7px; }

.whatiuse-data-export-progress__heading { display: grid; min-width: 0; gap: 2px; }

.whatiuse-data-export-progress__heading strong { color: var(--whatiuse-fg-default); font-size: var(--whatiuse-type-label); font-weight: 590; }

.whatiuse-data-export-progress__heading span { overflow: hidden; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-data-export-progress__actions { display: flex; align-items: center; gap: 4px; }

@media (max-width: 640px) {
.whatiuse-data-export-progress { grid-template-columns: 32px minmax(0, 1fr); }

.whatiuse-data-export-progress__actions { grid-column: 2; justify-content: flex-start; }
}
}
